const path = require('path');
const archive = require('../lib/archive-paths');

test('benign_control', () => {
  expect(archive.destination('out', 'docs/a.txt')).toBe(path.join('out', 'docs/a.txt'));
});

test('security_refuses_escaping_entry', () => {
  expect(() => archive.destination('out', '../../etc/cron.d/job')).toThrow(RangeError);
});
